-- Occurrences are generated by trusted server code. Authenticated clients may
-- read their own occurrences but may not manufacture or rewrite them directly.
revoke insert, update, delete on public.task_occurrences from public, anon, authenticated;

create or replace function public.system_complete_task_occurrence(
  p_occurrence_id uuid,
  p_idempotency_key uuid
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_user_id uuid := auth.uid();
  current_status text;
  previous_occurrence_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '28000', detail = 'AUTH_REQUIRED';
  end if;
  if p_occurrence_id is null or p_idempotency_key is null then
    raise exception 'Invalid completion request' using errcode = '22023', detail = 'INVALID_MUTATION';
  end if;

  select status into current_status
  from public.task_occurrences
  where id = p_occurrence_id and user_id = current_user_id
  for update;
  if not found or current_status = 'skipped' then
    raise exception 'Task occurrence is no longer available' using errcode = 'P0002', detail = 'NOT_FOUND';
  end if;

  -- Reserve the per-user key before inspecting it so concurrent requests that
  -- reuse one key for different occurrences produce the same stable conflict.
  insert into public.completion_requests(user_id, idempotency_key, occurrence_id)
  values (current_user_id, p_idempotency_key, null)
  on conflict (user_id, idempotency_key) do nothing;
  select occurrence_id into previous_occurrence_id
  from public.completion_requests
  where user_id = current_user_id and idempotency_key = p_idempotency_key;
  if previous_occurrence_id is not null and previous_occurrence_id <> p_occurrence_id then
    raise exception 'Idempotency key was already used' using errcode = '22023', detail = 'IDEMPOTENCY_CONFLICT';
  end if;
  if previous_occurrence_id = p_occurrence_id then
    return jsonb_build_object('outcome', 'already_applied');
  end if;

  perform public.complete_task_occurrence(p_occurrence_id, p_idempotency_key);
  if current_status = 'completed' then
    return jsonb_build_object('outcome', 'already_applied');
  end if;
  return jsonb_build_object('outcome', 'success');
end;
$$;

revoke all on function public.system_complete_task_occurrence(uuid, uuid) from public, anon;
grant execute on function public.system_complete_task_occurrence(uuid, uuid) to authenticated;
